"""Marvin limited-mode controller for round_dough_sheet.
Run phases explicitly; every phase connects to the live episode without resetting it.
"""
import json, os, sys, time
from pathlib import Path
import numpy as np
sys.path.insert(0, '/opt/tools')
from rcb_client import Robot, EpisodeOver

OUT = Path('/app/output')
RUNS = OUT / 'runs'
RUNS.mkdir(exist_ok=True)


def latest_obs(r, tag):
    o = r.get_obs(depth=True, video='none')
    o.save(str(OUT / tag))
    return o


def tcp(obs, arm):
    p = np.asarray(obs.meta['proprio']['now'], dtype=float)[16:30]
    return p[:7] if arm == 'right' else p[7:14]


def seed_q(obs):
    return np.asarray(obs.meta['proprio']['now'][:14], dtype=float)[[0,1,2,3,4,5,6,8,9,10,11,12,13,14]]


def vertical_quat(sign=1):
    # Tool z points down; tool x (finger closure) points +/- world y.
    return np.array([0., np.sqrt(.5), sign*np.sqrt(.5), 0.])


def ee_row(right_pose, left_pose, right_open=.085, left_open=.085):
    return np.r_[right_pose[:3], right_pose[3:7], right_open,
                 left_pose[:3], left_pose[3:7], left_open].astype(np.float32)


def inspect_ik():
    r=Robot(); o=latest_obs(r, 'current')
    now=np.asarray(o.meta['proprio']['now'],dtype=float)
    q14=np.r_[now[:7],now[8:15]]
    print('meta', {k:o.meta.get(k) for k in ('time_left_s','step','control_steps','sim_time_s','done')})
    print('tcp right',now[16:23].round(4).tolist(),'left',now[23:30].round(4).tolist())
    for arm in ('right','left'):
        off=0 if arm=='right' else 7
        seed=q14[off:off+7]
        for y in (-.035,.035):
            for z in (.88,.84,.80,.77):
                pose=[.36,y,z,*vertical_quat(1)]
                target={f'Gripper_Tip_{arm[0].upper()}':pose}
                ans=r.ik(target,seed=q14, max_iters=300)
                key=f'Gripper_Tip_{arm[0].upper()}'
                print(arm, 'xyz',(.36,y,z),'ok',ans.get('ok'),'err',ans.get('error'), 'q',np.round(ans.get('q',[])[off:off+7],3).tolist() if ans.get('q') else None)


def main():
    if len(sys.argv)>1 and sys.argv[1]=='inspect': inspect_ik()
    else: print('Choose a phase after inspection.')

if __name__ == '__main__': main()
